def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        # We're at the start of a field
        if i == n:
            # End of line - if we just finished a field, we're done
            # Otherwise, we have an empty field
            if not fields:
                fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < n:
                if line[i] == '"':
                    # Possible end of quoted field or escaped quote
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Next character must be comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        if i < n:
                            i += 1  # Skip the comma
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < n:
                i += 1  # Skip the comma

    return fields

